import pandas as pd, numpy as np
from fleetrisk.schema import FEATURES
import sys; sys.path.insert(0,"src")
sd = pd.read_pickle("sd.pkl")
# group by exact ref score
gr = sd.groupby("risk_score")
sizes = gr.size()
multi = sizes[sizes>1]
print("ref-score groups with >1 row:", len(multi), "rows involved:", multi.sum())
bad_feats = {}
for score, grp in gr:
    if len(grp)<2: continue
    for c in FEATURES:
        if grp[c].round(9).nunique()>1:
            bad_feats[c] = bad_feats.get(c,0)+1
print(bad_feats)
EOF"}

